package com.rpb.reservation.workforce.scheduling.restswap;
import static com.rpb.reservation.workforce.scheduling.restswap.RestSwapDtos.*;import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;import com.rpb.reservation.workforce.scheduling.*;import com.rpb.reservation.workforce.scheduling.bulk.*;import com.rpb.reservation.walkin.api.CurrentActor;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service
public class RestSwapService {
 private final WorkforceAccess access;private final SchedulingRepository planning;private final BulkScheduleRepository bulk;private final WorkforceEmployeeRepository employees;private final RestSwapRepository rests;private final RestSwapPlanService plans;private final ScheduleService schedules;private final WorkforceAudit audit;private final WorkforceJson json;
 public RestSwapService(WorkforceAccess access,SchedulingRepository planning,BulkScheduleRepository bulk,WorkforceEmployeeRepository employees,RestSwapRepository rests,RestSwapPlanService plans,ScheduleService schedules,WorkforceAudit audit,WorkforceJson json){this.access=access;this.planning=planning;this.bulk=bulk;this.employees=employees;this.rests=rests;this.plans=plans;this.schedules=schedules;this.audit=audit;this.json=json;}
 @Transactional public Result commit(CurrentActor actor,UUID store,UUID command,Commit c){access.sourceWrite(actor);access.enter(actor,store);access.manage(actor,store);if(command==null||c==null||c.fingerprint()==null||!c.fingerprint().matches("[a-f0-9]{64}"))throw WorkforceException.invalid();var r=RestSwapPlanService.normalize(c.request());String hash=BulkSchedulePlanService.hash("rest-swap:"+json.write(new Commit(r,c.fingerprint())));planning.lockPlanning(actor.tenantId(),store,false);planning.lock("workforce.bulk:"+actor.tenantId()+":"+command);var replay=bulk.replayAs(actor.tenantId(),store,actor.actorId(),command,hash,Result.class);if(replay.isPresent())return replay.get();bulk.lockStore(actor.tenantId(),store);planning.lock("workforce.calendar:"+actor.tenantId()+":"+store);planning.lock("workforce.shift:"+r.shiftId());r.employeeIds().forEach(employees::lock);var preview=plans.preview(actor,store,r);if(!preview.fingerprint().equals(c.fingerprint()))throw new WorkforceException("WORKFORCE_BULK_CHANGED",409);if(preview.ready()==0)throw WorkforceException.invalid();var created=new ArrayList<UUID>();for(var item:preview.items())if(item.status().equals("ready")){for(var id:item.cancelSchedules()){var old=planning.find(actor.tenantId(),id).orElseThrow(WorkforceException::missing);schedules.save(actor,store,id,new SchedulingDtos.ScheduleWrite(old.version(),item.employeeId(),old.shiftId(),old.workDate(),"cancelled"));}UUID id=UUID.randomUUID();schedules.save(actor,store,id,new SchedulingDtos.ScheduleWrite(0L,item.employeeId(),r.shiftId(),r.makeupDate(),"scheduled"));created.add(id);}var result=new Result(command,created.size(),preview.conflicts(),List.copyOf(created));bulk.receiptValue(actor.tenantId(),store,actor.actorId(),command,hash,result);int index=0;for(var item:preview.items())if(item.status().equals("ready"))rests.save(actor.tenantId(),store,command,item.employeeId(),r.restDate(),r.makeupDate(),created.get(index++),item.cancelSchedules());audit.changed(actor,store,"schedule.rest-swap",command,r,result);return result;}
}
